public struct Vector2{public float x,y;public Vector2(float x,float y){this.x=x;this.y=y;}public static Vector2 zero{get{return new Vector2();}}public static Vector2 one{get{return new Vector2(1,1);}}public static Vector2 operator+(Vector2 a,Vector2 b){return new Vector2(a.x+b.x,a.y+b.y);}public static Vector2 operator-(Vector2 a,Vector2 b){return new Vector2(a.x-b.x,a.y-b.y);}public static Vector2 operator*(Vector2 a,float b){return new Vector2(a.x*b,a.y*b);}public static Vector2 Lerp(Vector2 a,Vector2 b,float t){return a+(b-a)*Mathf.Clamp01(t);}}
public struct Vector3{public static float Distance(Vector3 a,Vector3 b){var d=a-b;return(float)Math.Sqrt(d.x*d.x+d.y*d.y+d.z*d.z);}public static Vector3 operator+(Vector3 a,Vector3 b){return new Vector3(a.x+b.x,a.y+b.y,a.z+b.z);}public static Vector3 operator-(Vector3 a,Vector3 b){return new Vector3(a.x-b.x,a.y-b.y,a.z-b.z);}public static Vector3 operator*(Vector3 a,float n){return new Vector3(a.x*n,a.y*n,a.z*n);}public float x,y,z;public Vector3(float x,float y,float z){this.x=x;this.y=y;this.z=z;}public static Vector3 zero{get{return new Vector3();}}public static Vector3 one{get{return new Vector3(1,1,1);}}public static Vector3 Scale(Vector3 a,Vector3 b){return new Vector3(a.x*b.x,a.y*b.y,a.z*b.z);}public static Vector3 Lerp(Vector3 a,Vector3 b,float t){t=Mathf.Clamp01(t);return new Vector3(a.x+(b.x-a.x)*t,a.y+(b.y-a.y)*t,a.z+(b.z-a.z)*t);}}
