public struct Color{public static Color blue{get{return new Color(0,0,1);}}public static Color red{get{return new Color(1,0,0);}}public static Color operator*(Color a,Color b){return new Color(a.r*b.r,a.g*b.g,a.b*b.b,a.a*b.a);}public static Color black{get{return new Color(0,0,0);}}public float r,g,b,a;public Color(float r,float g,float b,float a=1){this.r=r;this.g=g;this.b=b;this.a=a;}public static Color white{get{return new Color(1,1,1);}}public static Color yellow{get{return new Color(1,1,0);}}public float maxColorComponent{get{return Math.Max(r,Math.Max(g,b));}}public static Color Lerp(Color a,Color b,float t){return new Color(a.r+(b.r-a.r)*t,a.g+(b.g-a.g)*t,a.b+(b.b-a.b)*t,a.a+(b.a-a.a)*t);}}
public static class Mathf{public const float PI=(float)Math.PI;public static float Sin(float value){return (float)Math.Sin(value);}public static float Pow(float a,float b){return(float)Math.Pow(a,b);}public static int Clamp(int v,int a,int b){return Math.Max(a,Math.Min(b,v));}public static float Abs(float n){return Math.Abs(n);}public static float Lerp(float a,float b,float t){return a+(b-a)*Clamp01(t);}public static float Min(float a,float b){return Math.Min(a,b);}public static float Clamp(float v,float a,float b){return Math.Max(a,Math.Min(b,v));}public static int CeilToInt(float v){return(int)Math.Ceiling(v);}public static float Max(float a,float b){return Math.Max(a,b);}public static int Max(int a,int b){return Math.Max(a,b);}public static float Clamp01(float n){return Math.Max(0,Math.Min(1,n));}public static float SmoothStep(float a,float b,float n){n=Clamp01(n);return a+(b-a)*(n*n*(3-2*n));}public static int FloorToInt(float n){return(int)Math.Floor(n);}}
